#include <hip/hip_runtime.h>

__global__ void swish_bias_kernel(
    const float* x,
    const float* bias,
    float* out,
    int batch_size,
    int out_features,
    bool use_bias
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_features;

    if (idx < total_elements) {
        float x_val = x[idx];
        float sigmoid_x = 1.0f / (1.0f + expf(-x_val));
        float swish_out = sigmoid_x * x_val;

        if (use_bias) {
            int feature_idx = idx % out_features;
            swish_out += bias[feature_idx];
        }

        out[idx] = swish_out;
    }
}

torch::Tensor swish_bias_hip(torch::Tensor x, torch::Tensor bias, bool use_bias) {
    int batch_size = x.size(0);
    int out_features = x.size(1);
    auto out = torch::empty_like(x);

    int total_elements = batch_size * out_features;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    swish_bias_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        use_bias ? bias.data_ptr<float>() : nullptr,
        out.data_ptr<float>(),
        batch_size,
        out_features,
        use_bias
    );

    return out;
}
