#include <hip/hip_runtime.h>

#define TILE_M 64
#define TILE_N 64
#define TILE_K 64

__global__ void matmul_swish_bias_kernel(
    const float* A,  // [batch_size, in_features]
    const float* B,  // [out_features, in_features] (weight, transposed)
    const float* bias,  // [out_features]
    float* C,  // [batch_size, out_features]
    int batch_size,
    int in_features,
    int out_features,
    bool use_bias
) {
    int c = blockIdx.x * TILE_N + threadIdx.x;
    int b = blockIdx.y * TILE_M + threadIdx.y;

    __shared__ float A_tile_shared[TILE_M][TILE_K];
    __shared__ float B_tile_shared[TILE_N][TILE_K];

    float sum = 0.0f;

    int num_tiles = (in_features + TILE_K - 1) / TILE_K;

    for (int t = 0; t < num_tiles; ++t) {
        int k_start = t * TILE_K;
        int k_end = min(k_start + TILE_K, in_features);
        int k_range = k_end - k_start;

        // Load A tile
        int a_row = threadIdx.y;
        int a_col_start = k_start + threadIdx.x;

        if (b < batch_size && a_col_start < in_features) {
            A_tile_shared[a_row][threadIdx.x] = A[b * in_features + a_col_start];
        }

        // Load B tile
        int b_row = threadIdx.x;
        int b_col_start = k_start + threadIdx.y;

        if (c < out_features && b_col_start < in_features) {
            B_tile_shared[b_row][threadIdx.y] = B[c * in_features + b_col_start];
        }

        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE_K && (k_start + k) < k_end; ++k) {
            float a_val = A_tile_shared[threadIdx.y][k];
            float b_val = B_tile_shared[threadIdx.x][k];
            sum += a_val * b_val;
        }

        __syncthreads();
    }

    if (b < batch_size && c < out_features) {
        float sigmoid_x = 1.0f / (1.0f + expf(-sum));
        float swish_out = sigmoid_x * sum;

        if (use_bias) {
            swish_out += bias[c];
        }

        C[b * out_features + c] = swish_out;
    }
